def gen(rng):

    def make(n, mode, lo, hi):
        val = [rng.randint(lo, hi) for _ in range(n)]
        L = [-1] * n
        R = [-1] * n
        slots = [(0, 0), (0, 1)]
        for i in range(1, n):
            if mode == 'chainL':
                p, s = i - 1, 0
            elif mode == 'chainR':
                p, s = i - 1, 1
            elif mode == 'zig':
                p, s = i - 1, i % 2
            else:
                k = rng.randrange(len(slots))
                slots[k], slots[-1] = slots[-1], slots[k]
                p, s = slots.pop()
                slots.append((i, 0))
                slots.append((i, 1))
            if s == 0:
                L[p] = i
            else:
                R[p] = i
        out = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(val[u]))
            q.append(L[u])
            q.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

